import os
import json
from google.cloud import documentai_v1 as documentai

def validate_document_fields(payload, config=None):
    config = config or {}
    client = documentai.DocumentProcessorServiceClient()
    processor_name = f"projects/{config.get('project_id', os.getenv('GOOGLE_CLOUD_PROJECT_ID'))}/locations/{config.get('location', 'us')}/processors/{config.get('processor_id', os.getenv('DOCUMENT_AI_PROCESSOR_ID', 'your-processor-id'))}"

    # Supported file types: https://cloud.google.com/document-ai/docs/file-types
    with open(payload["file_path"], "rb") as file:
        document = {"content": file.read(), "mime_type": payload["mime_type"]}

    request = {"name": processor_name, "raw_document": document}
    result = client.process_document(request=request)

    validation_result = {
        "is_valid": True,
        "fields": {},
        "confidence_scores": {}
    }

    for entity in result.document.entities:
        field_name = entity.type_
        field_value = entity.mention_text
        confidence = entity.confidence

        if field_name in payload["required_fields"]:
            validation_result["fields"][field_name] = field_value
            validation_result["confidence_scores"][field_name] = confidence
            if confidence < config.get("min_confidence", 0.7):
                validation_result["is_valid"] = False

    return validation_result
